const UA='Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 Chrome/140.0.0.0 Safari/537.36';
const hosts=['www.riseup.co.il','signup.riseup.co.il']; const paths=['/wp-json/wp/v2/users?per_page=100','/wp-login.php?action=register','/wp-signup.php','/wp-json/wp/v2/types'];
for(const h of hosts)for(const p of paths){try{const r=await fetch('https://'+h+p,{redirect:'manual',headers:{'user-agent':UA,'accept':'application/json,text/html;q=0.9,*/*;q=0.8','cache-control':'no-cache'}});const b=await r.text();console.log('R',JSON.stringify({h,p,s:r.status,loc:r.headers.get('location'),ct:r.headers.get('content-type'),len:b.length,body:b.slice(0,5000)}));}catch(e){console.log('ERR',h,p,String(e))}}
